INSERT INTO public."categories" ("id", "name", "description", "slug", "created_at", "updated_at", "parent_id", "bg_image", "show_on_home") VALUES ('11', 'Star Wars KYLO REN', 'Embrace the Dark Side with this detailed Kylo Ren cosplay costume set inspired by the Star Wars sequel trilogy. The outfit includes a textured ribbed tunic jacket, matching slim trousers, a wide faux-leather waist belt, faux-leather gloves, and a long flowing black cape. Crafted from durable, comfortable materials with screen-accurate dark styling, it is ideal for Halloween, cosplay conventions, stage performances, and fan events.', 'star-wars-kylo-ren', '2026-08-25T19:02:09.835Z', '2026-09-24T20:00:51.344Z', NULL, '/uploads/136-1790280051160-640449561.jpg', true) ON CONFLICT DO NOTHING;
INSERT INTO public."categories" ("id", "name", "description", "slug", "created_at", "updated_at", "parent_id", "bg_image", "show_on_home") VALUES ('14', 'Darth Vender', 'Add the ultimate power of the Dark Side to your collection with this highly detailed Star Wars Darth Vader action figure. Featuring screen-accurate armor detailing, a real fabric cape, and his signature red lightsaber, this fully articulated 6-inch figure is perfect for both display and dynamic posing. A must-have centerpiece for any Star Wars fan or action figure collector.', 'darth-vender', '2026-08-25T19:02:10.478Z', '2026-09-24T19:56:49.843Z', NULL, '/uploads/117-1790279809678-889541927.jpg', true) ON CONFLICT DO NOTHING;
INSERT INTO public."categories" ("id", "name", "description", "slug", "created_at", "updated_at", "parent_id", "bg_image", "show_on_home") VALUES ('13', 'Star Wars The Mandalorian (Din Djarin)', 'Track bounties across the galaxy with this highly detailed Star Wars action figure of The Mandalorian (Din Djarin). Featuring a screen-accurate Beskar armor finish, textured flight suit detailing, a fabric cape, and his signature blaster pistol, this fully articulated figure is crafted for premium posability and display. An essential collectible for any Star Wars and Mandalorian fan.', 'star-wars-the-mandalorian-din-djarin', '2026-08-25T19:02:10.294Z', '2026-09-24T19:58:24.107Z', NULL, '/uploads/127-1790279903932-30379087.jpg', true) ON CONFLICT DO NOTHING;
INSERT INTO public."categories" ("id", "name", "description", "slug", "created_at", "updated_at", "parent_id", "bg_image", "show_on_home") VALUES ('15', 'Star Wars ROTJ SKYWALKER', 'Step into the role of a legendary Jedi Master with this complete Obi-Wan Kenobi cosplay costume set. Featuring a flowing brown hooded cloak, layered cream tunic, matching inner shirt, trousers, and a detailed faux-leather waist belt, this outfit captures screen-accurate cinematic detail. Crafted from comfortable, breathable fabrics, it is ideal for Halloween, comic conventions, themed parties, and Star Wars cosplay events.', 'star-wars-rotj-skywalker', '2026-08-25T19:02:10.809Z', '2026-09-24T19:59:46.659Z', NULL, '/uploads/145-1790279986492-919000037.jpg', true) ON CONFLICT DO NOTHING;
INSERT INTO public."size_guides" ("id", "title", "columns", "rows", "sort_order", "active", "created_at", "updated_at") VALUES ('9357f0bf-9757-49dc-bbd3-0e57370d50bd', 'Wall Clocks & Calligraphy Panels', '["Category","Standard Size (in)","Large Size (in)","Grand Size (in)"]'::jsonb, '[["Ayat-ul-Kursi Panels","12x24","18x36","24x48"],["DIY Wall Clocks","24x24 (needle length 6\")","36x36 (needle length 9\")","48x48 (needle length 12\")"],["Leafs Hanging Clocks","N/A","24x24","30x30"],["Set of 3 Sceneries","12x18 each","16x24 each","N/A"]]'::jsonb, 1, true, '2026-08-25T19:03:38.046Z', '2026-08-25T19:03:38.046Z') ON CONFLICT DO NOTHING;
INSERT INTO public."size_guides" ("id", "title", "columns", "rows", "sort_order", "active", "created_at", "updated_at") VALUES ('b9c13797-f6a6-4658-b5af-ad4c127a4457', 'Acrylic Mirror Butterfly & Hexagon Sets', '["Set Type","Total Pieces","Average Piece Size (in)","Recommended Wall Area (sq ft)"]'::jsonb, '[["Butterfly Set","16 Pcs","4x4 to 6x6","2 - 3 sq ft"],["Hexagon Set (Small)","12 Pcs","4.7x4.1","1.5 - 2 sq ft"],["Hexagon Set (Large)","24 Pcs","4.7x4.1","3 - 4 sq ft"]]'::jsonb, 2, true, '2026-08-25T19:03:38.269Z', '2026-08-25T19:03:38.269Z') ON CONFLICT DO NOTHING;
INSERT INTO public."products" ("id", "name", "slug", "description", "price", "stock", "category_id", "active", "featured", "sizes", "colors", "created_at", "updated_at", "sku", "material", "size_guide_id", "show_in_hero") VALUES ('12', 'Star Wars Kylo Ren Full Cosplay Costume Set with Cape, Tunic & Belt   ', 'star-wars-kylo-ren-full-cosplay-costume-set-with-cape-tunic-belt', 'Step into the role of the Supreme Leader with this premium Kylo Ren cosplay costume set. Inspired by the Star Wars sequel trilogy, this complete outfit features a textured ribbed tunic jacket, matching slim-fit pants, a long flowing black cape, a wide faux-leather belt, and gloves. Designed for both durability and comfort, it offers screen-accurate detailing perfect for Halloween, comic conventions, themed events, and cosplay photography.   ', '89.99', 120, '11', true, true, ARRAY['S', 'M', 'L', 'XL', 'XXL'], ARRAY['Black'], '2026-08-25T19:02:13.567Z', '2026-09-24T20:04:28.411Z', 'ACRYLIC-MIRR-512', 'Polyester, PU Faux Leather, Uniform Cloth   ', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public."products" ("id", "name", "slug", "description", "price", "stock", "category_id", "active", "featured", "sizes", "colors", "created_at", "updated_at", "sku", "material", "size_guide_id", "show_in_hero") VALUES ('10', 'Star Wars Obi-Wan Kenobi Jedi Knight Cosplay Costume Set with Robe & Belt   ', 'star-wars-obi-wan-kenobi-jedi-knight-cosplay-costume-set-with-robe-belt', 'Step into the role of a legendary Jedi Master with this complete Obi-Wan Kenobi cosplay costume set. Inspired by the Star Wars saga, this outfit includes a flowing hooded brown robe, layered cream tunic, matching undershirt, tailored pants, and a detailed faux-leather waist belt. Made from breathable, comfortable fabrics with screen-accurate detailing, it is perfect for Halloween, comic conventions, themed parties, and cosplay events.   ', '79.99', 25, '15', true, true, ARRAY['S', 'M', 'L', 'XL', 'XXL'], ARRAY['Brown', 'Beige', 'Cream'], '2026-08-25T19:02:12.555Z', '2026-09-24T20:10:01.087Z', 'BIG-FAMILY-F-757', 'Cotton Blend, Linen, PU Faux Leather, Uniform Cloth   ', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public."products" ("id", "name", "slug", "description", "price", "stock", "category_id", "active", "featured", "sizes", "colors", "created_at", "updated_at", "sku", "material", "size_guide_id", "show_in_hero") VALUES ('16', 'Star Wars The Mandalorian (Din Djarin) Full Beskar Armor Cosplay Costume Set with Cape & Belt   ', 'star-wars-the-mandalorian-din-djarin-full-beskar-armor-cosplay-costume-set-with-cape-belt', 'Suit up as the galaxy''s most renowned bounty hunter with this screen-accurate Mandalorian (Din Djarin) cosplay costume set. This detailed outfit features a textured flight suit, a full set of silver Beskar-style body armor pieces (chest, pauldrons, gauntlets, and leg guards), a long brown cape, bandolier, and a faux-leather utility belt with holster. Built from durable, comfortable materials, it is ideal for Halloween, comic conventions, fan expos, and cosplay photography.   ', '100.00', 190, '13', true, true, ARRAY['S', 'M', 'L', 'XL', 'XXL'], ARRAY['Silver', 'Brown', 'Grey'], '2026-09-24T20:14:33.826Z', '2026-10-10T09:28:57.867Z', 'STAR-WARS-THE-MANDALORIAN-DIN-DJARIN-FULL-BESKAR-ARMOR-COSPLAY-COSTUME-SET-WITH-CAPE-BELT', 'PU Faux Leather, Uniform Cloth, Polyester, EVA/Composite Armor Detailing   ', NULL, false) ON CONFLICT DO NOTHING;
