INSERT INTO public."testimonials" ("id", "name", "role", "subject", "content", "image_url", "created_at", "updated_at") VALUES ('8470d83c-ef7f-43ca-afd2-8ac9a1ac5bd4', 'MERI PIPENBAHER', 'Ui Designer', 'Amazing quality!', 'I used to spend hours writing creative copy, but now all I do is tell Rytr what I need and it writes everything for me. It''s the ultimate AI content writer, and a must-have tool for bloggers,marketers.', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=150&h=150&fit=crop', '2026-08-09T15:25:47.321Z', '2026-08-09T15:25:47.321Z') ON CONFLICT DO NOTHING;
INSERT INTO public."testimonials" ("id", "name", "role", "subject", "content", "image_url", "created_at", "updated_at") VALUES ('dfb89a8a-8bce-4f2e-9cc1-75b4a56e1bc6', 'SAM WISTER', 'Laravel Developer', 'Saves so much time', 'codexyard is a game-changer. Instead of drowning in an endless chain of emails, there is clear and easy accountability meaning tasks actually get done!', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=150&h=150&fit=crop', '2026-08-09T15:25:48.048Z', '2026-08-09T15:25:48.048Z') ON CONFLICT DO NOTHING;
INSERT INTO public."testimonials" ("id", "name", "role", "subject", "content", "image_url", "created_at", "updated_at") VALUES ('394e1539-804c-45dd-a434-3a888209438c', 'EMILA MARTINEZ', 'Social Media Manager', 'Highly recommended', 'I have been using codexyard for over a year now and I love it! I can''t imagine life without it. It''s so easy to use, and the customer service is great.', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=150&h=150&fit=crop', '2026-08-09T15:25:48.325Z', '2026-08-09T15:25:48.325Z') ON CONFLICT DO NOTHING;
