CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

CREATE TABLE IF NOT EXISTS public."_migrations" (
  "id" BIGSERIAL,
  "filename" text NOT NULL,
  "applied_at" timestamp with time zone DEFAULT now() NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."users" (
  "id" BIGSERIAL,
  "name" text NOT NULL,
  "email" text NOT NULL,
  "password" text NOT NULL,
  "role" text DEFAULT 'customer'::text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."categories" (
  "id" BIGSERIAL,
  "name" text NOT NULL,
  "description" text,
  "slug" text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "parent_id" bigint,
  "bg_image" text,
  "show_on_home" boolean DEFAULT true NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."size_guides" (
  "id" uuid DEFAULT uuid_generate_v4() NOT NULL,
  "title" VARCHAR(255) NOT NULL,
  "columns" jsonb DEFAULT '[]'::jsonb NOT NULL,
  "rows" jsonb DEFAULT '[]'::jsonb NOT NULL,
  "sort_order" integer DEFAULT 0,
  "active" boolean DEFAULT true,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."products" (
  "id" BIGSERIAL,
  "name" text NOT NULL,
  "slug" text NOT NULL,
  "description" text,
  "price" numeric DEFAULT 0 NOT NULL,
  "stock" integer DEFAULT 0 NOT NULL,
  "category_id" bigint,
  "active" boolean DEFAULT true NOT NULL,
  "featured" boolean DEFAULT false NOT NULL,
  "sizes" text[] DEFAULT '{}'::text[],
  "colors" text[] DEFAULT '{}'::text[],
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "sku" text,
  "material" text,
  "size_guide_id" uuid,
  "show_in_hero" boolean DEFAULT false,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."product_images" (
  "id" BIGSERIAL,
  "product_id" bigint NOT NULL,
  "url" text NOT NULL,
  "is_primary" boolean DEFAULT false NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "is_main" boolean DEFAULT false NOT NULL,
  "price" numeric,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."hero_content" (
  "id" BIGSERIAL,
  "title" text DEFAULT ''::text NOT NULL,
  "subtitle" text DEFAULT ''::text NOT NULL,
  "cta_text" text DEFAULT 'Shop Now'::text NOT NULL,
  "cta_link" text DEFAULT '/products'::text NOT NULL,
  "image_url" text,
  "active" boolean DEFAULT true NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."settings" (
  "id" BIGSERIAL,
  "company_name" text DEFAULT ''::text NOT NULL,
  "app_logo" text,
  "tagline" text DEFAULT ''::text NOT NULL,
  "intro" text DEFAULT ''::text NOT NULL,
  "phone" text DEFAULT ''::text NOT NULL,
  "whatsapp" text DEFAULT ''::text NOT NULL,
  "email" text DEFAULT ''::text NOT NULL,
  "address" text DEFAULT ''::text NOT NULL,
  "business_hours" text DEFAULT ''::text NOT NULL,
  "map_embed" text DEFAULT ''::text NOT NULL,
  "facebook" text DEFAULT ''::text NOT NULL,
  "linkedin" text DEFAULT ''::text NOT NULL,
  "instagram" text DEFAULT ''::text NOT NULL,
  "youtube" text DEFAULT ''::text NOT NULL,
  "brochure_url" text DEFAULT ''::text NOT NULL,
  "hero_bg" text,
  "hero_title" text DEFAULT ''::text NOT NULL,
  "hero_highlighted_text" text DEFAULT ''::text NOT NULL,
  "hero_subtitle" text DEFAULT ''::text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "cta_text" text DEFAULT 'Shop the Collection'::text NOT NULL,
  "cta_link" text DEFAULT '/products'::text NOT NULL,
  "app_favicon" text DEFAULT ''::text,
  "feature_1_title" text DEFAULT ''::text NOT NULL,
  "feature_1_desc" text DEFAULT ''::text NOT NULL,
  "feature_2_title" text DEFAULT ''::text NOT NULL,
  "feature_2_desc" text DEFAULT ''::text NOT NULL,
  "feature_3_title" text DEFAULT ''::text NOT NULL,
  "feature_3_desc" text DEFAULT ''::text NOT NULL,
  "social_links" jsonb DEFAULT '[]'::jsonb,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."contact_messages" (
  "id" BIGSERIAL,
  "name" text NOT NULL,
  "email" text NOT NULL,
  "subject" text NOT NULL,
  "message" text NOT NULL,
  "read" boolean DEFAULT false NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "country" text,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."testimonials" (
  "id" uuid DEFAULT uuid_generate_v4() NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "role" VARCHAR(255) NOT NULL,
  "subject" VARCHAR(255),
  "content" text NOT NULL,
  "image_url" VARCHAR(1024),
  "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."promotions" (
  "id" BIGSERIAL,
  "name" text NOT NULL,
  "discount_type" text DEFAULT 'percentage'::text NOT NULL,
  "discount_value" numeric DEFAULT 0 NOT NULL,
  "active" boolean DEFAULT true NOT NULL,
  "start_date" timestamp with time zone,
  "end_date" timestamp with time zone,
  "applies_to" text DEFAULT 'all'::text NOT NULL,
  "target_ids" int8[] DEFAULT '{}'::bigint[],
  "banner_title" text,
  "banner_subtitle" text,
  "banner_image_url" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."orders" (
  "id" BIGSERIAL,
  "user_id" bigint,
  "customer_name" text NOT NULL,
  "customer_email" text NOT NULL,
  "shipping_address" text NOT NULL,
  "shipping_city" text,
  "shipping_country" text,
  "shipping_zip" text,
  "phone" text,
  "total" numeric DEFAULT 0 NOT NULL,
  "status" text DEFAULT 'pending'::text NOT NULL,
  "payment_status" text DEFAULT 'pending'::text NOT NULL,
  "stripe_session_id" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "paypal_order_id" text,
  "paypal_capture_id" text,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."order_items" (
  "id" BIGSERIAL,
  "order_id" bigint NOT NULL,
  "product_id" bigint,
  "product_name" text NOT NULL,
  "price" numeric DEFAULT 0 NOT NULL,
  "quantity" integer DEFAULT 1 NOT NULL,
  "size" text,
  "color" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."page_views" (
  "id" BIGSERIAL,
  "path" text NOT NULL,
  "visitor_id" text,
  "session_id" text,
  "referrer" text,
  "user_agent" text,
  "ip" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "country" text,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."blogs" (
  "id" SERIAL,
  "title" VARCHAR(255) NOT NULL,
  "slug" VARCHAR(255) NOT NULL,
  "content" text NOT NULL,
  "image_url" text,
  "author" VARCHAR(255),
  "is_published" boolean DEFAULT false,
  "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
  "meta_title" text,
  "meta_description" text,
  "meta_keywords" text,
  "meta_schema" text,
  "image_alt" text,
  "category" text,
  "description" text,
  "faqs" jsonb DEFAULT '[]'::jsonb,
  "faq_schema_enabled" boolean DEFAULT false,
  "custom_faq_schema" text,
  "related_articles" jsonb DEFAULT '[]'::jsonb,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."faqs" (
  "id" BIGSERIAL,
  "question" text NOT NULL,
  "answer" text NOT NULL,
  "category_id" bigint,
  "product_id" bigint,
  "is_general" boolean DEFAULT false,
  "active" boolean DEFAULT true,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id")
);

ALTER TABLE public."products" ADD COLUMN IF NOT EXISTS "size_guide_id" UUID;
ALTER TABLE public."products" ADD COLUMN IF NOT EXISTS "show_in_hero" BOOLEAN DEFAULT false;
ALTER TABLE public."products" ADD COLUMN IF NOT EXISTS "material" TEXT;
ALTER TABLE public."products" ADD COLUMN IF NOT EXISTS "sku" TEXT;
ALTER TABLE public."orders" ADD COLUMN IF NOT EXISTS "payment_method" TEXT DEFAULT 'paypal';
ALTER TABLE public."orders" ADD COLUMN IF NOT EXISTS "paypal_order_id" TEXT;
ALTER TABLE public."orders" ADD COLUMN IF NOT EXISTS "paypal_capture_id" TEXT;

